def findPairDifference(nums, k):
    if len(nums) < 2:
        return False
    counts = {}
    for x in nums:
        counts[x] = counts.get(x, 0) + 1
    if k == 0:
        return any(v >= 2 for v in counts.values())
    for x in counts:
        if (x + k) in counts:
            return True
    return False

