import java.util.*;
public class Solution {
    public boolean findPairDifference(int[] nums, int k) {
        if (nums.length < 2) return false;
        Map<Integer, Integer> counts = new HashMap<>();
        for (int x : nums) counts.put(x, counts.getOrDefault(x, 0) + 1);
        if (k == 0) {
            for (int c : counts.values()) if (c >= 2) return true;
            return false;
        }
        for (int x : counts.keySet()) if (counts.containsKey(x + k)) return true;
        return false;
    }
}

