#include <vector>
#include <unordered_map>
using namespace std;
class Solution {
public:
    bool findPairDifference(vector<int>& nums, int k) {
        if (nums.size() < 2) return false;
        unordered_map<int, int> counts;
        for (int x : nums) counts[x]++;
        if (k == 0) {
            for (auto& p : counts) if (p.second >= 2) return true;
            return false;
        }
        for (auto& p : counts) if (counts.count(p.first + k)) return true;
        return false;
    }
};
